import{_ as e,o as i,c as o,a5 as t}from"./chunks/framework.CXvGqWf0.js";const p=JSON.parse('{"title":"漫画 · 第 37 话 View Transitions 进阶：跨页转场与工程化","description":"","frontmatter":{},"headers":[],"relativePath":"comics/css/EP.37-view-transitions-advanced.md","filePath":"comics/css/EP.37-view-transitions-advanced.md","lastUpdated":1793421609000}'),n={name:"comics/css/EP.37-view-transitions-advanced.md"};function s(r,a,c,d,l,h){return i(),o("div",null,[...a[0]||(a[0]=[t('<h1 id="漫画-·-第-37-话-view-transitions-进阶-跨页转场与工程化" tabindex="-1">漫画 · 第 37 话 View Transitions 进阶：跨页转场与工程化 <a class="header-anchor" href="#漫画-·-第-37-话-view-transitions-进阶-跨页转场与工程化" aria-label="Permalink to &quot;漫画 · 第 37 话 View Transitions 进阶：跨页转场与工程化&quot;">​</a></h1><blockquote><p>对应正文：<a href="./../../docs/css/24-view-transitions-advanced">docs/css/24-view-transitions-advanced.md</a> ｜ 原画：<a href="./EP.37-view-transitions-advanced.svg">EP.37-view-transitions-advanced.svg</a></p></blockquote><h2 id="登场角色" tabindex="-1">登场角色 <a class="header-anchor" href="#登场角色" aria-label="Permalink to &quot;登场角色&quot;">​</a></h2><ul><li><strong>像素酱</strong>：CSS 造型师，本话主角。被 MPA 站点「点击链接白屏闪切」困扰，又被 20 个卡片各写一组伪元素动画规则搞到崩溃。</li><li><strong>标签君</strong>：HTML5 结构师，搬出三把进阶钥匙——<code>@view-transition</code> 跨页自动转场、<code>view-transition-class</code> 批量复用、<code>active-view-transition-type</code> 类型化控制。</li></ul><h2 id="剧情梗概" tabindex="-1">剧情梗概 <a class="header-anchor" href="#剧情梗概" aria-label="Permalink to &quot;剧情梗概&quot;">​</a></h2><p>像素酱的基础 View Transitions 在 SPA 里玩得很溜，但 MPA 多页站还是白屏闪切；20 个卡片各写一组 <code>::view-transition-old/new</code>，动画规则爆炸；不同转场（展开/收起/删除）共用一套动画，视觉语义混乱。标签君引入进阶三件套：CSS 一行 <code>@view-transition { navigation: auto }</code> 让 MPA 获得 SPA 级转场；<code>view-transition-class: zoom</code> 批量复用动画规则；<code>active-view-transition-type(expand)</code> 按转场类型匹配不同动画。像素酱发现纯 MPA 架构已能超越多数 SPA 的体验。</p><h2 id="分格解读" tabindex="-1">分格解读 <a class="header-anchor" href="#分格解读" aria-label="Permalink to &quot;分格解读&quot;">​</a></h2><h3 id="格1-·-痛点现场" tabindex="-1">格1 · 痛点现场 <a class="header-anchor" href="#格1-·-痛点现场" aria-label="Permalink to &quot;格1 · 痛点现场&quot;">​</a></h3><p>MPA 站点切换像 PPT：A 页点击链接→白屏→B 页。为了转场效果被迫引入前端路由框架，打包体积激增。20 个卡片各写一组伪元素规则，维护成本极高。不同转场类型（展开/收起/删除）没有区分机制，全是同一套淡入淡出。</p><h3 id="格2-·-机制登场" tabindex="-1">格2 · 机制登场 <a class="header-anchor" href="#格2-·-机制登场" aria-label="Permalink to &quot;格2 · 机制登场&quot;">​</a></h3><p>三把钥匙：跨页自动转场（<code>@view-transition { navigation: auto }</code> 一行开启，同站导航自动拍快照补间）、<code>view-transition-class</code> 批量复用（<code>.item { view-transition-class: zoom }</code> + <code>::view-transition-group(*.zoom)</code> 一条规则批量命中）、<code>active-view-transition-type</code> 类型化控制（<code>expand</code> 用圆形扩散、<code>collapse</code> 用圆形收缩、删除用缩小消失）。</p><h3 id="格3-·-落地收束" tabindex="-1">格3 · 落地收束 <a class="header-anchor" href="#格3-·-落地收束" aria-label="Permalink to &quot;格3 · 落地收束&quot;">​</a></h3><p>四大进阶场景：MPA 跨页转场（两页都需声明 <code>@view-transition</code>）、view-transition-class 批量复用（动画规则不再重复）、active-view-transition-type 按类型区分动画、滚动与手势联动（scroll-snap + VT 配合，手势驱动草案级）。Chrome 126+ 独占，Safari/Firefox 渐进增强。</p><h2 id="码叔划重点" tabindex="-1">码叔划重点 <a class="header-anchor" href="#码叔划重点" aria-label="Permalink to &quot;码叔划重点&quot;">​</a></h2><ol><li><code>@view-transition { navigation: auto }</code> 开启 MPA 跨页转场，两页都需声明。</li><li><code>view-transition-class</code> 批量复用动画规则；<code>view-transition-name</code> 仍须全局唯一。</li><li><code>active-view-transition-type()</code> 按转场类型区分动画，expand/collapse/删除各用各的。</li></ol><h2 id="自测一题" tabindex="-1">自测一题 <a class="header-anchor" href="#自测一题" aria-label="Permalink to &quot;自测一题&quot;">​</a></h2><p><strong>问</strong>：MPA 站 A 页声明了 <code>@view-transition { navigation: auto }</code>，B 页没有声明。用户从 A 点击链接到 B，会发生 view transition 吗？</p><p><strong>答</strong>：不会。跨页转场要求新旧页面都声明 <code>@view-transition { navigation: auto }</code>，否则浏览器不会启动转场机制。这是最常见的「明明配置了却不起效」的坑。</p><h2 id="动手实验" tabindex="-1">动手实验 <a class="header-anchor" href="#动手实验" aria-label="Permalink to &quot;动手实验&quot;">​</a></h2><ul><li>view-transition-class 批量复用 + active-view-transition-type 类型化 + MPA 跨页提示 + 滚动联动：<a href="./../../examples/css/24-view-transitions-advanced/index-01-view-transitions-advanced.html">examples/css/24-view-transitions-advanced/</a></li></ul><h2 id="下一话预告" tabindex="-1">下一话预告 <a class="header-anchor" href="#下一话预告" aria-label="Permalink to &quot;下一话预告&quot;">​</a></h2><p>第 38 话《Speculation Rules》——<code>&lt;script type=&quot;speculationrules&quot;&gt;</code> 让浏览器在后台预渲染下一页，点击时 LCP ≈ 0ms，与 View Transitions 配合实现「瞬时导航 + 动画」的 MPA 终极体验。</p>',22)])])}const u=e(n,[["render",s]]);export{p as __pageData,u as default};
